*{box-sizing:border-box;margin:0;padding:0}

.pg{width:794px;height:1123px;background:var(--cr);position:relative;overflow:hidden;box-shadow:0 12px 40px rgba(35,36,58,.16);border-radius:4px;flex:none}
.pg:before{content:'';position:absolute;inset:0;background:radial-gradient(circle at 92% 6%,rgba(76,111,255,.06),transparent 32%),radial-gradient(circle at 4% 96%,rgba(245,184,61,.08),transparent 30%);pointer-events:none}
.pg .wm{position:absolute;left:50%;top:52%;width:127px;transform:translate(-50%,-50%);opacity:.16;pointer-events:none;z-index:0}
.pg .ph{position:absolute;left:0;right:0;top:0;height:54px;display:flex;align-items:center;justify-content:space-between;padding:0 36px;z-index:3;background:linear-gradient(180deg,#fff,rgba(255,253,248,.94))}
.pg .ph:after{content:'';position:absolute;left:36px;right:36px;bottom:0;height:3px;border-radius:3px;background:linear-gradient(90deg,var(--ma),var(--coral) 30%,var(--g) 60%,var(--blue) 85%,transparent)}
.ph img.lg{height:28px}
.ph .pl{font-size:10px;font-weight:800;letter-spacing:.16em;color:var(--ma);text-transform:uppercase}
.ph .pc{font-size:10px;font-weight:700;color:#fff;background:linear-gradient(90deg,var(--blue),var(--violet));padding:5px 12px;border-radius:20px;max-width:260px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pg .pf{position:absolute;left:0;right:0;bottom:0;height:42px;display:flex;align-items:center;justify-content:space-between;padding:0 36px;font-size:9.6px;color:var(--mut);z-index:3;background:linear-gradient(0deg,#fff,rgba(255,253,248,.92));border-top:1px solid var(--line)}
.pf b{color:var(--ma)}
.pf .pn{background:var(--ma);color:var(--g);font-weight:800;padding:4px 11px;border-radius:14px;font-size:10.5px;letter-spacing:.04em}
.pg .bd{position:absolute;left:0;right:0;top:54px;bottom:42px;padding:18px 38px 12px;z-index:1;display:flex;flex-direction:column;gap:10px;font-size:12.6px;line-height:1.55}
.pg.nohf .bd{top:0;bottom:0;padding:0}
.pg .bd>*{flex-shrink:0}
.ic3{display:inline-block;object-fit:contain;flex:none;filter:drop-shadow(0 3px 4px rgba(35,36,58,.18))}
/* tiêu đề */
.hd .eb,.eb{font-size:10.2px;font-weight:800;letter-spacing:.17em;text-transform:uppercase;color:var(--coral)}
.hd h1{font-size:25px;line-height:1.2;font-weight:800;color:var(--ma);margin-top:3px;letter-spacing:-.01em}
.hd .ul{display:block;width:56px;height:4px;border-radius:3px;background:linear-gradient(90deg,var(--coral),var(--g));margin:7px 0 2px}
.lead{font-size:13.4px;color:#474b63;line-height:1.55}
.bd b{color:var(--ma)}
.tx{color:#33364d}
.h2{font-size:15px;font-weight:800;color:var(--ink);display:flex;align-items:center;gap:8px;margin-top:2px}
.h2:before{content:'';width:6px;height:18px;border-radius:3px;background:var(--kc,var(--blue))}
.h2 .ic3{margin-left:-2px}
.ul2{list-style:none;display:flex;flex-direction:column;gap:5px}
.ul2 li{position:relative;padding-left:18px;color:#33364d}
.ul2 li:before{content:'';position:absolute;left:3px;top:.55em;width:8px;height:8px;border-radius:50%;background:var(--kc)}
.grid{display:grid}
.colw{display:flex;flex-direction:column;gap:10px;min-width:0}
.ctr{display:flex;justify-content:center;align-items:center}
/* màu */
.k-blue{--kc:var(--blue);--kl:var(--blue-l)}.k-teal{--kc:var(--teal);--kl:var(--teal-l)}.k-green{--kc:var(--green);--kl:var(--green-l)}
.k-gold{--kc:var(--gold);--kl:var(--gold-l)}.k-coral{--kc:var(--coral);--kl:var(--coral-l)}.k-violet{--kc:var(--violet);--kl:var(--violet-l)}
.k-rose{--kc:var(--rose);--kl:var(--rose-l)}.k-slate{--kc:var(--slate);--kl:var(--slate-l)}.k-maroon{--kc:var(--maroon);--kl:var(--maroon-l)}
/* thẻ */
.card{position:relative;background:#fff;border:1.5px solid color-mix(in srgb,var(--kc) 28%,#fff);border-radius:16px;padding:11px 13px;box-shadow:0 4px 0 color-mix(in srgb,var(--kc) 22%,#fff),0 10px 22px -12px rgba(35,36,58,.25)}
.card .ch{display:flex;align-items:center;gap:10px}
.card .ch b{display:block;font-size:13.6px;line-height:1.25;color:var(--ink)}
.card .ch small{display:block;font-size:10.6px;font-weight:700;color:var(--kc);letter-spacing:.02em;margin-top:1px}
.card .cb{margin-top:7px;font-size:11.8px;line-height:1.5;color:#474b63}
.card .cnum{position:absolute;right:10px;top:8px;width:22px;height:22px;border-radius:50%;background:var(--kl);color:var(--kc);font-weight:800;font-size:11px;display:grid;place-items:center}
.mini{display:flex;align-items:center;gap:9px;background:var(--kl);border-radius:12px;padding:8px 11px;border:1px solid color-mix(in srgb,var(--kc) 22%,#fff)}
.mini b{display:block;font-size:12px;line-height:1.25}.mini small{display:block;font-size:10.4px;color:var(--mut);line-height:1.3}
/* hộp chú thích */
.box{border-radius:14px;padding:9px 13px 10px;border:1.5px dashed var(--bc);background:var(--bl)}
.box .bxh{display:flex;align-items:center;gap:7px;font-size:10.4px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--bc)}
.box .bxh b{font-size:12.6px;letter-spacing:0;text-transform:none;color:var(--ink);margin-left:4px}
.box .bxb{margin-top:4px;font-size:12px;line-height:1.52;color:#3b3e55}
.b-quick{--bc:#C98F12;--bl:#FFF7E3}.b-ex{--bc:#0E9F9A;--bl:#E8F8F6}.b-tip{--bc:#23A660;--bl:#EAF8EF}.b-warn{--bc:#F0604F;--bl:#FFEDEA}
.b-deep{--bc:#7C5CF0;--bl:#F3EFFF;border-style:solid}.b-new{--bc:#E0457B;--bl:#FFEEF4}.b-chk{--bc:#4C6FFF;--bl:#EEF2FF}
/* flow */
.flow{display:flex;align-items:stretch;gap:6px}
.flow.v{flex-direction:column;align-items:stretch}
.flow .fn{flex:1;min-width:0;position:relative;background:#fff;border-radius:14px;padding:10px 8px 9px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:4px;
 border:1.5px solid color-mix(in srgb,var(--kc) 35%,#fff);box-shadow:0 4px 0 color-mix(in srgb,var(--kc) 25%,#fff)}
.flow.v .fn{flex-direction:row;text-align:left;padding:8px 12px;gap:10px}
.flow .fn b{font-size:12px;line-height:1.25;color:var(--ink)}
.flow .fn small{font-size:10.2px;line-height:1.35;color:var(--mut)}
.flow.v .fn b{display:block}.flow.v .fn>div{display:flex;flex-direction:column}
.flow .fnum{position:absolute;left:-6px;top:-7px;width:20px;height:20px;border-radius:50%;background:var(--kc);color:#fff;font-size:10.5px;font-weight:800;display:grid;place-items:center;box-shadow:0 2px 5px rgba(0,0,0,.2)}
.flow .fa{display:grid;place-items:center;color:#9aa3c7;font-weight:900;font-size:18px;flex:none}
.flow.v .fa{height:14px;font-size:14px;line-height:1}
.flow.sm .fn{padding:7px 6px}.flow.sm .fn b{font-size:11px}.flow.sm .fn small{font-size:9.6px}
.steps{display:flex;flex-direction:column;gap:7px}
.st{display:flex;align-items:center;gap:10px;background:#fff;border-radius:12px;padding:8px 12px;border-left:5px solid var(--kc);box-shadow:0 6px 16px -10px rgba(35,36,58,.3)}
.st .sn{width:24px;height:24px;flex:none;border-radius:50%;background:var(--kl);color:var(--kc);font-weight:800;font-size:12px;display:grid;place-items:center}
.st b{display:block;font-size:12.4px}.st small{display:block;font-size:11px;color:var(--mut);line-height:1.4}
/* vòng lặp */
.cycle{position:relative;margin:0 auto}
.cycle .cyr{position:absolute;left:0;top:0}
.cyn{position:absolute;transform:translate(-50%,-50%);background:#fff;border:1.5px solid color-mix(in srgb,var(--kc) 40%,#fff);border-radius:14px;padding:6px 9px;display:flex;flex-direction:column;align-items:center;gap:2px;min-width:78px;box-shadow:0 4px 0 color-mix(in srgb,var(--kc) 25%,#fff)}
.cyn b{font-size:11px;line-height:1.2;text-align:center}
.cyc{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:3px;text-align:center;max-width:110px}
.cyc b{font-size:12px;color:var(--ma);line-height:1.2}
/* sơ đồ */
.dg{position:relative;margin:0 auto}
.dg-svg{position:absolute;left:0;top:0;overflow:visible}
.dg-n{position:absolute;display:flex;align-items:center;justify-content:center;gap:7px;text-align:center;padding:4px 8px;z-index:2}
.dg-n b{display:block;font-size:11.4px;line-height:1.22;color:var(--ink)}
.dg-n small{display:block;font-size:9.6px;line-height:1.25;color:var(--mut)}
.dg-box{background:#fff;border:1.8px solid var(--kc);border-radius:12px;box-shadow:0 4px 0 color-mix(in srgb,var(--kc) 28%,#fff)}
.dg-pill{background:var(--kl);border:1.8px solid var(--kc);border-radius:999px}
.dg-circle{background:var(--kl);border:2px solid var(--kc);border-radius:50%;flex-direction:column;gap:2px}
.dg-ghost{background:transparent}
.dg-db{background:var(--kl);border:1.8px solid var(--kc);border-radius:50%/16%;flex-direction:column;gap:1px}
.dg-doc{background:#fff;border:1.8px solid var(--kc);border-radius:6px 6px 14px 6px;box-shadow:3px 3px 0 var(--kl)}
.dg-diamond{padding:0}.dg-diamond svg{position:absolute;left:0;top:0}.dgd{fill:var(--kl);stroke:var(--kc);stroke-width:2}
.dg-diamond .dgi{position:relative;display:flex;align-items:center;gap:5px;padding:0 18%}
.dg-diamond b{font-size:10.6px}
.dg-lab{position:absolute;transform:translate(-50%,-50%);font-size:9.8px;font-weight:800;background:var(--cr);padding:1px 6px;border-radius:8px;white-space:nowrap;z-index:3}
/* khối 3D */
.b3{position:relative;flex:none}
.b3 .b3t{position:absolute;background:color-mix(in srgb,var(--kc) 42%,#fff);transform:skewX(-45deg);transform-origin:0 100%;border-radius:2px 2px 0 0}
.b3 .b3s{position:absolute;background:color-mix(in srgb,var(--kc) 70%,#1d1f33);transform:skewY(-45deg);transform-origin:0 0}
.b3 .b3f{position:absolute;left:0;bottom:0;background:linear-gradient(180deg,color-mix(in srgb,var(--kc) 88%,#fff),var(--kc));color:#fff;border-radius:2px;display:flex;align-items:center;justify-content:center;gap:8px;padding:4px 10px;text-align:center;box-shadow:0 10px 18px -8px rgba(0,0,0,.35)}
.b3 .b3f b{color:#fff;display:block;font-size:12.6px;line-height:1.2}.b3 .b3f small{display:block;font-size:9.8px;opacity:.92;line-height:1.25}
.tower{display:flex;flex-direction:column;align-items:center}
.iso{position:relative;width:calc(var(--w) * 1.42);margin:0 auto}
.isl{position:absolute;left:50%;width:var(--w);height:var(--w);margin-left:calc(var(--w) / -2);transform:translateY(calc(var(--w) * -0.19)) scaleY(.56) rotate(45deg);
 background:linear-gradient(135deg,color-mix(in srgb,var(--kc) 55%,#fff),var(--kc));border-radius:16px;box-shadow:10px 10px 0 color-mix(in srgb,var(--kc) 60%,#222),0 30px 40px -10px rgba(0,0,0,.25);display:grid;place-items:center}
.isl span{transform:rotate(-45deg) scaleY(1.6);color:#fff;font-weight:900;font-size:14px;text-align:center;text-shadow:0 2px 4px rgba(0,0,0,.25);max-width:70%;line-height:1.15}
/* code, terminal, chat, cửa sổ */
.code,.term,.win,.chat{border-radius:14px;overflow:hidden;box-shadow:0 14px 30px -14px rgba(20,22,40,.5)}
.cdh{display:flex;align-items:center;gap:6px;padding:7px 12px;background:#2b2e45}
.cdh i{width:10px;height:10px;border-radius:50%;background:#ff6058}.cdh i+i{background:#ffbd2e}.cdh i+i+i{background:#28c840}
.cdh span{margin-left:8px;font-size:10.4px;color:#b8bdd6;font-family:'JBM','JetBrains Mono',monospace}
.cdb{background:#1d2033;padding:9px 0;font-family:'JBM','JetBrains Mono',monospace;font-size:10.6px;line-height:1.55;color:#e3e6f4}
.cl{display:flex;padding:0 12px 0 0;white-space:pre}
.cl i{width:30px;flex:none;text-align:right;padding-right:10px;color:#5c6185;font-style:normal}
.cl.hl{background:rgba(245,184,61,.16);box-shadow:inset 3px 0 0 var(--g)}
.c-kw{color:#c792ea}.c-st{color:#c3e88d}.c-cm{color:#8a92b8;font-style:italic}.c-nu{color:#f78c6c}
.term .tb{background:#151726;padding:9px 13px;font-family:'JBM',monospace;font-size:10.6px;line-height:1.6}
.term .tc{color:#7DF0C0}.term .to{color:#cfd3e8;white-space:pre-wrap}
.win .wb{background:#fff;padding:10px 12px}
.chat{background:#fff;border:1px solid var(--line)}
.chh{display:flex;align-items:center;gap:7px;padding:7px 12px;background:linear-gradient(90deg,var(--blue-l),var(--violet-l));font-size:11px;font-weight:800;color:var(--ink)}
.chb{padding:9px 11px;display:flex;flex-direction:column;gap:6px}
.msg{max-width:86%;padding:7px 11px;border-radius:14px;font-size:11.4px;line-height:1.45}
.m-u{align-self:flex-end;background:var(--blue);color:#fff;border-bottom-right-radius:4px}
.m-a{align-self:flex-start;background:#F1F2F8;color:var(--ink);border-bottom-left-radius:4px}
.m-s{align-self:center;background:var(--gold-l);color:#7a5a10;font-size:10.4px;font-family:'JBM',monospace;border-radius:8px}
/* bảng */
.tw{max-width:100%;overflow:hidden;border-radius:12px;border:1px solid var(--line);background:#fff}
.tbl{width:100%;border-collapse:collapse;font-size:11.4px;table-layout:fixed}
.tbl th{background:var(--kc);color:#fff;text-align:left;padding:7px 9px;font-size:11px;font-weight:800}
.tbl td{padding:6px 9px;border-top:1px solid #eee9de;vertical-align:top;line-height:1.42;color:#33364d;overflow-wrap:anywhere}
.tbl tr:nth-child(even) td{background:color-mix(in srgb,var(--kl) 55%,#fff)}
.tbl td:first-child{font-weight:700;color:var(--ink)}
.tbl.sm{font-size:10.6px}.tbl.sm td{padding:5px 8px}
/* so sánh */
.vs{display:grid;grid-template-columns:1fr 34px 1fr;align-items:stretch;gap:6px}
.vsc{background:var(--kl);border-radius:14px;padding:10px 12px;border:1.5px solid color-mix(in srgb,var(--kc) 30%,#fff)}
.vsh{display:flex;align-items:center;gap:8px;margin-bottom:6px}.vsh b{font-size:13px;color:var(--ink)}
.vsc ul{list-style:none;display:flex;flex-direction:column;gap:4px}
.vsc li{font-size:11.6px;line-height:1.42;padding-left:14px;position:relative;color:#3b3e55}.vsc li:before{content:'•';position:absolute;left:2px;color:var(--kc);font-weight:900}
.vsm{display:grid;place-items:center;font-weight:900;font-size:13px;color:#fff;background:linear-gradient(180deg,var(--coral),var(--violet));border-radius:999px;align-self:center;height:34px}
/* công thức, số, tag */
.fx{background:#fff;border:1.5px solid var(--violet-l);border-left:5px solid var(--violet);border-radius:12px;padding:9px 14px;text-align:center}
.fxe{font-family:'Cambria Math','Times New Roman',serif;font-size:17px;color:#2a2550}
.fxn{font-size:10.6px;color:var(--mut);margin-top:3px}
.stat{background:#fff;border-radius:14px;padding:10px 12px;display:flex;flex-direction:column;align-items:center;text-align:center;gap:2px;border:1.5px solid color-mix(in srgb,var(--kc) 30%,#fff)}
.stat b{font-size:24px;color:var(--kc);line-height:1.05;font-weight:900}.stat span{font-size:10.6px;color:var(--mut);line-height:1.35}
.tags{display:flex;flex-wrap:wrap;gap:6px}
.tag{font-size:10.6px;font-weight:700;color:var(--kc);background:var(--kl);border:1px solid color-mix(in srgb,var(--kc) 30%,#fff);padding:3px 10px;border-radius:999px}
.bars{display:flex;flex-direction:column;gap:6px}
.br{display:grid;grid-template-columns:96px 1fr 48px;align-items:center;gap:8px;font-size:10.8px}
.br span{color:#3b3e55;text-align:right}.br b{font-size:11px}
.bt{height:14px;background:#f0eee6;border-radius:8px;overflow:hidden}.bt i{display:block;height:100%;background:linear-gradient(90deg,color-mix(in srgb,var(--kc) 60%,#fff),var(--kc));border-radius:8px}
.hand{font-family:'Pangolin',cursive;font-size:15px;color:var(--kc);display:inline-block}
.hnote{position:absolute;font-family:'Pangolin',cursive;font-size:13.5px;line-height:1.25;color:var(--kc);z-index:4}
.pnl{background:linear-gradient(180deg,color-mix(in srgb,var(--kl) 80%,#fff),#fff);border:1.5px solid color-mix(in srgb,var(--kc) 22%,#fff);border-radius:18px;padding:12px 14px}
.pnh{display:flex;align-items:center;gap:8px;margin-bottom:8px}.pnh b{font-size:12.6px;color:var(--ink)}
/* trang mở chương */
.pg.opener .bd{padding:0}
.op{position:absolute;inset:0;overflow:hidden}
.opbg{position:absolute;inset:0;background:radial-gradient(circle at 78% 30%,color-mix(in srgb,var(--kc) 30%,#fff) 0,transparent 46%),linear-gradient(160deg,color-mix(in srgb,var(--kl) 90%,#fff),#fff 60%,var(--kl))}
.opbg:after{content:'';position:absolute;inset:0;background-image:radial-gradient(color-mix(in srgb,var(--kc) 25%,transparent) 1.2px,transparent 1.4px);background-size:22px 22px;opacity:.5;-webkit-mask:linear-gradient(180deg,#000,transparent 70%)}
.opnum{position:absolute;left:46px;top:40px;font-size:190px;font-weight:900;line-height:1;color:transparent;-webkit-text-stroke:3px color-mix(in srgb,var(--kc) 55%,#fff);letter-spacing:-.04em}
.opk{position:absolute;left:52px;top:250px;font-size:13px;font-weight:900;letter-spacing:.3em;color:var(--kc)}
.opt{position:absolute;left:50px;right:330px;top:276px;font-size:44px;line-height:1.08;font-weight:900;color:var(--ma);letter-spacing:-.02em}
.ops{position:absolute;left:52px;right:330px;top:420px;font-size:15px;line-height:1.55;color:#4a4e66}
.opic{position:absolute;right:30px;top:60px;width:330px;height:440px}
.opic .fl{position:absolute;filter:drop-shadow(0 14px 18px rgba(35,36,58,.25))}
.fl0{left:70px;top:70px}.fl1{left:10px;top:250px}.fl2{left:210px;top:20px}.fl3{left:200px;top:260px}.fl4{left:110px;top:330px}
.opw{position:absolute;left:46px;right:46px;top:640px;display:flex;gap:14px;align-items:flex-start;background:#fff;border-radius:18px;padding:16px 20px;border:1.5px solid color-mix(in srgb,var(--kc) 30%,#fff);border-left:6px solid var(--kc);box-shadow:0 14px 30px -18px rgba(35,36,58,.45)}
.opw b{display:block;font-size:14px;color:var(--ma);margin-bottom:4px}.opw span{font-size:13px;line-height:1.55;color:#40445c}
.opl{position:absolute;left:46px;right:46px;bottom:40px;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.opi{display:flex;align-items:center;gap:11px;background:rgba(255,255,255,.88);border:1.5px solid color-mix(in srgb,var(--kc) 25%,#fff);border-radius:14px;padding:10px 13px;font-size:13px;font-weight:700;box-shadow:0 8px 20px -14px rgba(35,36,58,.4)}


/* ───── 3D isometric & khung kiến trúc ───── */
.s3{position:relative;margin:0 auto;flex:none}
.s3>svg{position:absolute;left:0;top:0;overflow:visible}
.s3-bg{background:linear-gradient(180deg,#F5F8FF,#fff);border-radius:16px}
.s3-ic{position:absolute;transform:translate(-50%,-100%);z-index:3;line-height:0}
.s3-lt{position:absolute;transform:translate(-50%,-50%);text-align:center;z-index:4;pointer-events:none}
.s3-lt b{display:inline-block;font-size:10.6px;line-height:1.15;color:#1d1f33;background:rgba(255,255,255,.88);padding:2px 7px;border-radius:7px;white-space:nowrap;box-shadow:0 2px 6px rgba(0,0,0,.12)}
.s3-lt small{display:block;font-size:9px;color:#4a4e66;margin-top:1px}
.s3-lf{position:absolute;transform:translate(-50%,0);text-align:center;z-index:4;white-space:nowrap}
.s3-lf b{display:inline-block;font-size:10.4px;line-height:1.15;color:#fff;background:var(--kc);padding:2px 8px;border-radius:7px;box-shadow:0 3px 8px -3px rgba(0,0,0,.35)}
.s3-lf small{display:block;font-size:9px;color:#4a4e66;margin-top:2px}
.s3-tag{position:absolute;transform:translate(-100%,-50%);margin-left:-8px;z-index:4;font-size:10px;font-weight:900;letter-spacing:.06em;color:var(--kc);background:#fff;border:1.5px solid var(--kc);border-radius:8px;padding:2px 8px;white-space:nowrap}
.s3-pill{position:absolute;transform:translate(-50%,-50%);z-index:5;font-size:10.2px;font-weight:800;background:#fff;border:1.5px solid;border-radius:999px;padding:2px 8px;white-space:nowrap;box-shadow:0 3px 8px -4px rgba(0,0,0,.3)}
.s3-num{position:absolute;transform:translate(-50%,-50%);z-index:6;width:22px;height:22px;border-radius:50%;background:#7A1E2C;color:#F5B83D;font-size:11px;font-weight:900;display:grid;place-items:center;box-shadow:0 0 0 3px #fff,0 4px 8px rgba(0,0,0,.25)}
.l3{position:relative;width:100%}.l3>.s3{position:absolute;left:0;top:0;margin:0}
.l3-ln{position:absolute;border-top:2px dashed var(--kc);z-index:2}
.l3-r{position:absolute;right:0;display:flex;z-index:3;flex-direction:column;padding:6px 10px 6px 16px;border-left:3px solid var(--kc);background:linear-gradient(90deg,color-mix(in srgb,var(--kl) 85%,#fff),transparent);border-radius:0 10px 10px 0}
.l3-r b{font-size:12.6px;color:var(--ink)}.l3-r span{font-size:10.8px;color:var(--mut);line-height:1.35}
.t3-lab{text-align:center;font-size:10.6px;font-weight:700;color:var(--mut);margin-top:2px}
.lg3{display:grid;gap:6px 14px}
.lg3-i{display:flex;gap:8px;align-items:flex-start}.lg3-i span{flex:none;width:20px;height:20px;border-radius:50%;background:#7A1E2C;color:#F5B83D;font-size:10.5px;font-weight:900;display:grid;place-items:center;margin-top:1px}
.lg3-i b{display:block;font-size:11.6px;line-height:1.25}.lg3-i small{display:block;font-size:10.4px;color:var(--mut);line-height:1.35}
.bp{border-radius:18px;padding:12px 14px 12px;background:linear-gradient(#ffffff,#ffffff) padding-box,linear-gradient(135deg,var(--kc),#7A1E2C) border-box;border:2px solid transparent;position:relative;overflow:hidden}
.bp:before{content:'';position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--kc) 9%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--kc) 9%,transparent) 1px,transparent 1px);background-size:20px 20px;pointer-events:none}
.bp>*{position:relative}
.bp-h{display:flex;align-items:center;gap:10px;margin-bottom:6px;flex-wrap:wrap}.bp-t{font-size:9.6px;font-weight:900;letter-spacing:.18em;color:#fff;background:var(--kc);padding:4px 9px;border-radius:6px}
.bp-h b{font-size:14px;color:var(--ink)}.bp-h em{margin-left:auto;font-style:normal;font-size:10.4px;color:var(--mut)}
.bp-c{display:flex;justify-content:center}
.cs3{border-radius:18px;background:#fff;border:1.5px solid color-mix(in srgb,var(--kc) 30%,#fff);box-shadow:0 14px 30px -20px rgba(35,36,58,.5);overflow:hidden}
.cs3-h{display:flex;align-items:center;gap:8px;padding:7px 14px;background:linear-gradient(90deg,var(--kc),color-mix(in srgb,var(--kc) 60%,#7A1E2C));color:#fff}
.cs3-h span{font-size:10.4px;font-weight:900;letter-spacing:.16em}.cs3-h em{margin-left:auto;font-style:normal;font-size:10.6px;font-weight:700;opacity:.95}
.cs3-t{display:flex;align-items:center;gap:10px;padding:10px 14px 2px}.cs3-t b{font-size:15px;color:var(--ink);line-height:1.25}
.cs3-p{margin:6px 14px 0;font-size:11.8px;line-height:1.5;color:#3b3e55;background:var(--kl);border-radius:10px;padding:7px 10px}.cs3-p i{font-style:normal;font-weight:900;color:var(--kc);margin-right:6px}
.cs3-b{padding:10px 14px}
.cs3-l{display:flex;gap:8px;align-items:flex-start;margin:0 14px 12px;padding:7px 10px;border-radius:10px;background:#FFF7E3;font-size:11.6px;line-height:1.45;color:#5a4410}
.zm{display:grid;gap:30px;position:relative}
.zm-a,.zm-b{background:#fff;border-radius:16px;border:1.5px solid var(--line);padding:8px 10px;position:relative}
.zm-b{border:2px solid #F0604F;box-shadow:0 14px 30px -18px rgba(240,96,79,.6)}
.zm-a:after{content:'';position:absolute;right:-30px;top:30%;width:30px;height:40%;background:linear-gradient(90deg,rgba(240,96,79,.08),rgba(240,96,79,.18));clip-path:polygon(0 30%,100% 0,100% 100%,0 70%)}
.zm-l{display:flex;align-items:center;gap:6px;font-size:10.4px;font-weight:900;letter-spacing:.08em;color:var(--mut);text-transform:uppercase;margin-bottom:4px}
.jr3-h{font-size:12px;font-weight:800;margin-bottom:6px}
.jr3-row{display:grid;gap:6px;position:relative}
.jr3-row:before{content:'';position:absolute;left:4%;right:4%;top:22px;border-top:3px dashed #c9cfe3}
.jr3-s{position:relative;text-align:center;display:flex;flex-direction:column;align-items:center;gap:2px}
.jr3-d{width:46px;height:46px;border-radius:50%;background:#fff;border:2.5px solid var(--kc);display:grid;place-items:center;box-shadow:0 6px 12px -6px rgba(0,0,0,.35);position:relative;z-index:1}
.jr3-ms{font-size:9.6px;font-weight:900;color:#fff;background:var(--kc);border-radius:999px;padding:1px 7px;margin-top:2px}
.jr3-s b{font-size:11px;line-height:1.2}.jr3-s small{font-size:9.8px;color:var(--mut);line-height:1.3}
